const menu=document.querySelector('.menu'),nav=document.querySelector('.links');menu?.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',open);menu.textContent=open?'Zamknij':'Menu';});nav?.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));document.querySelectorAll('form').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();const s=f.querySelector('.form-status');s.classList.add('visible');s.textContent='To podgląd formularza — wiadomość nie została wysłana. Na gotowej stronie trafi do wybranego biura.';}));